{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Membership Pricing — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfc;--muted:#6b7280;--accent:#0f766e;--card:#ffffff;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#0f172a;background:linear-gradient(180deg,#f8fafb 0%,#ffffff 60%)}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#065f46);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:var(--muted);text-decoration:none;font-weight:600}
    .container{max-width:1100px;margin:28px auto;padding:24px}
    .hero{background:linear-gradient(90deg,rgba(15,118,110,0.06),rgba(6,95,70,0.02));padding:28px;border-radius:12px;display:flex;gap:20px;align-items:center}
    .hero h1{margin:0;font-size:22px;color:#052f2b}
    .hero p{margin:6px 0 0;color:var(--muted)}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:20px}
    .card{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 6px 18px rgba(9,30,66,0.04);border:1px solid rgba(15,23,42,0.03)}
    .card h3{margin:0;font-size:16px}
    .price{font-size:28px;color:var(--accent);margin-top:10px}
    .features{margin:12px 0;color:var(--muted);font-size:14px}
    .cta{display:inline-block;margin-top:12px;padding:10px 14px;border-radius:8px;background:var(--accent);color:white;text-decoration:none}
    .mini{font-size:13px;color:var(--muted)}
    .habit-builder{margin-top:28px;padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff 0,#fbfffd 100%);border:1px solid rgba(15,23,42,0.03)}
    label{display:block;font-size:13px;color:#0f172a;margin-top:10px}
    input[type=text],select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid #e6eef0;background:white}
    .controls{display:flex;gap:8px;margin-top:12px}
    button{background:var(--accent);color:white;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    .checklist{margin-top:14px}
    .checklist table{width:100%;border-collapse:collapse}
    .checklist th,.checklist td{border:1px solid #eef2f2;padding:8px;text-align:left}
    .print-only{display:none}
    footer{margin-top:36px;padding:20px;color:var(--muted);font-size:13px;text-align:center}
    .muted{color:var(--muted)}
    /* Decorative pattern */
    .pattern{position:absolute;right:10px;top:80px;opacity:0.08;width:320px;height:320px;background-image:url('assets/img/pattern.svg');background-size:cover;pointer-events:none}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Plans</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Testimonials</a>
      <a href="book.html">Book a Session</a>
      <a href="contact.html">Reach Out</a>
    </nav>
  </header>

  <div class="container">
    <div class="hero">
      <div>
        <h1>Membership tiers to support steady lifestyle shifts</h1>
        <p>An ongoing membership model that combines guided frameworks, weekly check-ins, and micro-practices — for moving habits into your life with predictable steps.</p>
      </div>
      <div style="margin-left:auto;text-align:right">
        <div class="mini">Ready to join?</div>
        <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </div>

    <section class="plans" aria-label="Membership plans">
      <div class="card">
        <h3>Starter Cycle</h3>
        <div class="price">$39 / month</div>
        <div class="features">
          - Monthly check-in + 2 micro-assignments
          <br>- Access to weekly guides
        </div>
        <div class="mini">Best for those testing sustainable patterns</div>
        <a class="cta" href="book.html" style="margin-top:10px;display:inline-block">Start with a session</a>
      </div>

      <div class="card">
        <h3>Momentum Membership</h3>
        <div class="price">$89 / month</div>
        <div class="features">
          - Weekly short sessions + habit templates
          <br>- Priority messaging between sessions
        </div>
        <div class="mini">Recommended for building a reliable weekly routine</div>
        <a class="cta" href="book.html">Join Momentum</a>
      </div>

      <div class="card">
        <h3>Sustained Flow</h3>
        <div class="price">$159 / month</div>
        <div class="features">
          - Bi-weekly deep sessions + bespoke plan
          <br>- Quarterly plan reviews
        </div>
        <div class="mini">For long-term change and accountability</div>
        <a class="cta" href="book.html">Claim a spot</a>
      </div>
    </section>

    <section class="habit-builder">
      <h2 style="margin:0">7‑Day Habit Challenge — Create a printable checklist</h2>
      <p class="muted" style="margin-top:6px">Design a simple seven-day practice and print or copy the checklist to carry with you.</p>

      <label for="habit">What habit will you try for 7 days?</label>
      <input id="habit" type="text" placeholder="e.g., Short morning stretch, 10-minute walk, Evening wind-down">

      <label for="reminder">Daily reminder note (optional)</label>
      <input id="reminder" type="text" placeholder="e.g., Do this before breakfast">

      <label for="difficulty">Select intensity</label>
      <select id="difficulty">
        <option>Easy — small, consistent actions</option>
        <option>Moderate — 10–20 minutes daily</option>
        <option>Ambitious — a focused daily commitment</option>
      </select>

      <div class="controls">
        <button id="generate">Generate Checklist</button>
        <button id="copyTxt" style="background:#475569">Copy Plaintext</button>
        <button id="printChk" style="background:#065f46">Print Checklist</button>
      </div>

      <div class="checklist" id="checklist" aria-live="polite"></div>
    </section>

    <div style="margin-top:22px;display:flex;gap:12px;align-items:center">
      <div style="flex:1">
        <div style="font-weight:700">Want to discuss which membership fits you?</div>
        <div class="muted">Book an introductory session to align on focus and immediate next steps.</div>
      </div>
      <div>
        <a class="cta" href="book.html">Schedule a Conversation</a>
      </div>
    </div>

    <footer>
      <div>{{BUSINESS_NAME}} &middot; <a href="tel:{{PHONE}}">{{PHONE}}</a> &middot; <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div style="margin-top:6px" class="muted">Membership terms are focused on behavioral frameworks and habit support; not medical advice.</div>
    </footer>
  </div>

  <div class="pattern" aria-hidden="true"></div>

  <script>
    // Habit builder (7-day) - local only
    (function(){
      const elHabit = document.getElementById('habit');
      const elReminder = document.getElementById('reminder');
      const elDifficulty = document.getElementById('difficulty');
      const btnGen = document.getElementById('generate');
      const btnCopy = document.getElementById('copyTxt');
      const btnPrint = document.getElementById('printChk');
      const out = document.getElementById('checklist');

      function makeChecklist(habit, reminder, difficulty){
        if(!habit) return '<div class="muted">Enter a habit to generate a checklist.</div>';
        let notes = reminder?('<div style="margin-top:8px;color:#334155;font-size:13px">Note: '+escapeHtml(reminder)+'</div>'):'<div style="margin-top:8px;color:#334155;font-size:13px">No reminder set</div>';
        let html = '<div style="font-weight:700;font-size:16px">7‑Day Checklist: '+escapeHtml(habit)+'</div>' + notes + '<table style="margin-top:12px"><thead><tr><th style="width:90px">Day</th><th>Target</th><th style="width:110px">Done</th></tr></thead><tbody>';
        for(let d=1;d<=7;d++){
          html += '<tr><td>Day '+d+'</td><td>'+escapeHtml(suggestTarget(habit,d,difficulty))+'</td><td><input type="checkbox" aria-label="Day '+d+'"/></td></tr>';
        }
        html += '</tbody></table>';
        html += '<div style="margin-top:10px;color:var(--muted);font-size:13px">Tip: Keep the target concise so it remains actionable each day.</div>';
        return html;
      }

      function suggestTarget(habit, day, difficulty){
        // lightweight suggestions to vary the daily micro-goal
        let base = habit;
        if(difficulty.includes('Easy')){
          return base + ' — 1 simple repetition (2–5 minutes)';
        }
        if(difficulty.includes('Moderate')){
          return base + ' — 10–15 minutes focused';
        }
        return base + ' — full dedicated session (20+ minutes)';
      }

      function escapeHtml(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

      btnGen.addEventListener('click',function(){
        out.innerHTML = makeChecklist(elHabit.value.trim(), elReminder.value.trim(), elDifficulty.value);
        out.scrollIntoView({behavior:'smooth',block:'center'});
      });

      btnCopy.addEventListener('click',function(){
        if(!elHabit.value.trim()) return alert('Please enter a habit first.');
        let lines = ['7-Day Checklist: '+elHabit.value.trim()];
        if(elReminder.value.trim()) lines.push('Note: '+elReminder.value.trim());
        for(let d=1;d<=7;d++){
          lines.push('Day '+d+': '+stripHtml(suggestTarget(elHabit.value.trim(),d,elDifficulty.value)));
        }
        navigator.clipboard.writeText(lines.join('\n')).then(()=>{
          alert('Checklist copied to clipboard.');
        },()=>{alert('Unable to copy.');});
      });

      btnPrint.addEventListener('click',function(){
        if(!elHabit.value.trim()) return alert('Please create a checklist first.');
        const printWindow = window.open('','Print','width=600,height=700');
        printWindow.document.write('<html><head><title>Checklist</title><style>body{font-family:Arial,Helvetica,sans-serif;padding:20px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}</style></head><body>');
        printWindow.document.write(out.innerHTML);
        printWindow.document.write('</body></html>');
        printWindow.document.close();
        printWindow.focus();
        setTimeout(()=>printWindow.print(),250);
      });

      function stripHtml(s){return s.replace(/<[^>]*>?/gm,'');}
    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--accent:#0f766e;--muted:#6b7280}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,#ffffff 0%,#f7f9fa 100%);color:#02121b}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#065f46,#0f766e);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:1000px;margin:22px auto;padding:18px}
    .lead{background:linear-gradient(90deg,rgba(15,118,110,0.06),rgba(6,95,70,0.02));padding:20px;border-radius:12px}
    .lead h1{margin:0;font-size:20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}
    .cards{display:flex;flex-direction:column;gap:14px}
    .card{background:#fff;padding:16px;border-radius:12px;border:1px solid rgba(2,18,27,0.04);box-shadow:0 6px 18px rgba(9,30,66,0.04)}
    .author{font-weight:700}
    .snippet{color:var(--muted);margin-top:6px}
    aside .card{position:sticky;top:20px}
    .habit-builder{padding:16px;border-radius:12px;background:linear-gradient(180deg,#fff 0,#fbfffd 100%);border:1px solid rgba(15,23,42,0.03)}
    label{display:block;margin-top:10px;font-size:13px}
    input[type=text],select{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:1px solid #e6eef0}
    .controls{display:flex;gap:8px;margin-top:12px}
    button{background:var(--accent);color:white;border:0;padding:10px 12px;border-radius:8px;cursor:pointer}
    .muted{color:var(--muted)}
    footer{margin-top:30px;text-align:center;color:var(--muted);padding-bottom:30px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Plans</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Testimonials</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="lead">
      <h1>Real outcomes from steady steps</h1>
      <p class="muted" style="margin-top:8px">Short stories from people who shaped a practical habit pattern and saw improved daily balance and better energy for priorities.</p>
    </section>

    <div class="grid">
      <div class="cards">
        <article class="card">
          <div class="author">Maya, project manager</div>
          <div class="snippet">"Weekly micro-tasks and the accountability prompts helped me keep small wins consistent; I can plan creative work in the mornings without stress."</div>
        </article>

        <article class="card">
          <div class="author">Omar, small business owner</div>
          <div class="snippet">"The coach reframed my to-do list into three simple daily anchors. That structure made it possible to keep a healthier rhythm across busy weeks."</div>
        </article>

        <article class="card">
          <div class="author">Lina, teacher</div>
          <div class="snippet">"I appreciated the habit templates — short, repeatable prompts that fit into school days and built momentum across a term."</div>
        </article>

        <article class="card">
          <div class="author">Testimonial placeholder</div>
          <div class="snippet">"If you'd like to share your story, reach out at <a href=\"mailto:{{EMAIL}}\">{{EMAIL}}</a>."</div>
        </article>
      </div>

      <aside>
        <div class="card habit-builder" aria-labelledby="hb">
          <h3 id="hb">Create a 7‑Day Challenge — printable</h3>
          <p class="muted">A quick tool to turn one intention into a 7‑day checklist. Use it with your membership or standalone.</p>

          <label for="habit2">Habit idea</label>
          <input id="habit2" type="text" placeholder="e.g., Evening disconnect from screens">

          <label for="reminder2">Reminder</label>
          <input id="reminder2" type="text" placeholder="e.g., Set a 30-min tech curfew">

          <label for="difficulty2">Intensity</label>
          <select id="difficulty2">
            <option>Easy — very short actions</option>
            <option>Moderate — 10–20 min</option>
            <option>Ambitious — 20+ min</option>
          </select>

          <div class="controls">
            <button id="gen2">Make Checklist</button>
            <button id="copy2" style="background:#475569">Copy Text</button>
          </div>

          <div id="out2" style="margin-top:12px"></div>
        </div>

        <div class="card" style="margin-top:14px">
          <div style="font-weight:700">Ready to explore this approach?</div>
          <div class="muted" style="margin-top:6px">Book a session to tailor a practical plan aligned with your week.</div>
          <div style="margin-top:10px"><a class="cta" href="book.html" style="display:inline-block;padding:8px 12px;border-radius:8px;background:var(--accent);color:#fff;text-decoration:none">Schedule a Call</a></div>
        </div>
      </aside>
    </div>

    <footer style="margin-top:22px;color:var(--muted);font-size:13px">Stories are presented with permission. Frameworks, habit tools, and coaching are not medical advice. Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></footer>
  </main>

  <script>
    // Lightweight habit builder for sidebar
    (function(){
      const h = document.getElementById('habit2');
      const r = document.getElementById('reminder2');
      const d = document.getElementById('difficulty2');
      const g = document.getElementById('gen2');
      const c = document.getElementById('copy2');
      const o = document.getElementById('out2');

      function buildText(habit,reminder,difficulty){
        if(!habit) return 'Enter a habit idea to generate text.';
        let lines = ['7-Day Challenge: '+habit];
        if(reminder) lines.push('Reminder: '+reminder);
        for(let i=1;i<=7;i++) lines.push('Day '+i+': '+suggest(habit,i,difficulty));
        return lines.join('\n');
      }

      function suggest(habit,i,diff){
        if(diff.includes('Easy')) return habit+' — 1 small repetition';
        if(diff.includes('Moderate')) return habit+' — 10–15 minutes focused';
        return habit+' — 20+ minutes dedicated work';
      }

      g.addEventListener('click',()=>{
        o.textContent = buildText(h.value.trim(),r.value.trim(),d.value);
      });

      c.addEventListener('click',()=>{
        const txt = buildText(h.value.trim(),r.value.trim(),d.value);
        if(!h.value.trim()){alert('Please enter a habit idea.');return}
        navigator.clipboard.writeText(txt).then(()=>alert('Copied to clipboard.'),()=>alert('Copy failed.'));
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book a Session — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#0f766e;--muted:#6b7280}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:#fbfdfe;color:#042022}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#0f766e,#065f46);display:flex;align-items:center;justify-content:center;color:white}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none;font-weight:600}
    .wrap{max-width:1000px;margin:24px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:18px}
    .panel{background:#fff;padding:18px;border-radius:12px;border:1px solid rgba(2,18,27,0.04)}
    h1{margin:0 0 6px 0}
    p.muted{color:var(--muted);margin-top:6px}
    label{display:block;margin-top:10px;font-size:14px}
    input[type=text],textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid #e6eef0;margin-top:6px}
    .btn{background:var(--accent);color:white;padding:10px 12px;border-radius:8px;border:0;cursor:pointer}
    .session-plan{margin-top:14px;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff 0,#f6fffd 100%);border:1px solid rgba(15,23,42,0.03)}
    pre{white-space:pre-wrap;background:#f8fafb;padding:12px;border-radius:8px;border:1px dashed #e6eef0}
    .mini{font-size:13px;color:var(--muted)}
    footer{margin-top:20px;color:var(--muted);font-size:13px;text-align:center}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Story</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Plans</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Testimonials</a>
      <a href="book.html">Book</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="panel">
        <h1>Book a Session</h1>
        <p class="muted">Choose a session length and build a tailored session plan using the Session Planner tool below. After you create the plan, copy the summary and include it in your booking message.</p>

        <label for="name">Your name</label>
        <input id="name" type="text" placeholder="Full name">

        <label for="email">Email</label>
        <input id="email" type="text" placeholder="you@example.com">

        <label for="sessionType">Session focus</label>
        <select id="sessionType">
          <option>Kickoff: Align priorities & immediate actions (60 min)</option>
          <option>Weekly check-in & micro-tasks (30 min)</option>
          <option>Deep planning session (90 min)</option>
        </select>

        <label for="when">Preferred date/time (suggested)</label>
        <input id="when" type="text" placeholder="e.g., Week of Mar 1, mornings preferred">

        <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
          <button class="btn" id="submitBooking">Request Booking</button>
          <div class="mini">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        </div>

        <div style="margin-top:18px" class="session-plan">
          <h3 style="margin:0 0 8px 0">Session Planner</h3>
          <p class="mini">Build a simple session agenda and a short plan you can copy into your booking message.</p>

          <label for="goal">Primary goal for this session</label>
          <input id="goal" type="text" placeholder="What outcome would help most?">

          <label for="duration">Preferred session length</label>
          <select id="duration">
            <option>30 minutes</option>
            <option>45 minutes</option>
            <option>60 minutes</option>
            <option>90 minutes</option>
          </select>

          <label for="focusAreas">Focus areas (comma separated)</label>
          <input id="focusAreas" type="text" placeholder="e.g., sleep routine, energy peaks, weekly planning">

          <label for="followUp">Follow-up preference</label>
          <select id="followUp">
            <option>Email summary + 3 next steps</option>
            <option>Plan + 7-day checklist</option>
            <option>Weekly micro-checks for 1 month</option>
          </select>

          <div style="display:flex;gap:8px;margin-top:10px">
            <button id="build">Build Plan</button>
            <button id="copyPlan" style="background:#475569">Copy Summary</button>
            <button id="downloadPlan" style="background:#065f46">Download as .txt</button>
          </div>

          <div style="margin-top:12px">
            <pre id="planOut">No plan yet. Use "Build Plan" to create a short agenda and follow-ups.</pre>
          </div>
        </div>

      </section>

      <aside class="panel">
        <h3 style="margin-top:0">How this works</h3>
        <p class="muted">The planner creates a concise agenda and three clear follow-ups you can act on right away. It's meant to keep sessions targeted and practical.</p>

        <div style="margin-top:14px">
          <div style="font-weight:700">Need a different arrangement?</div>
          <div class="muted" style="margin-top:6px">Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> with your needs or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</div>
        </div>
      </aside>
    </div>

    <footer>
      <div class="mini">By requesting a booking you agree to coordinate scheduling and any membership details. Coaching frameworks focus on habits and behaviors; not medical advice.</div>
    </footer>
  </main>

  <script>
    // Session Planner: builds a plaintext summary, copy and download
    (function(){
      const goal = document.getElementById('goal');
      const duration = document.getElementById('duration');
      const focus = document.getElementById('focusAreas');
      const followUp = document.getElementById('followUp');
      const build = document.getElementById('build');
      const out = document.getElementById('planOut');
      const cp = document.getElementById('copyPlan');
      const dl = document.getElementById('downloadPlan');

      function generate(){
        const g = goal.value.trim() || 'Define a short, clear objective';
        const dur = duration.value;
        const f = focus.value.trim()?focus.value.trim().split(',').map(s=>s.trim()).filter(Boolean):[];
        const fu = followUp.value;

        const agenda = [];
        agenda.push('Session Objective: '+g);
        agenda.push('Duration: '+dur);
        if(f.length) agenda.push('Focus areas: '+f.join(', '));

        // Build 3-part agenda
        agenda.push('\nProposed agenda:');
        agenda.push('1) Quick review of current patterns (10% of session)');
        agenda.push('2) Targeted exploration around "'+(f[0]||g)+'" (60% of session)');
        agenda.push('3) Concrete next steps and a check-in plan (remaining time)');

        // Follow-ups
        agenda.push('\nFollow-up:');
        if(fu.includes('7-day')){
          agenda.push('- Provide a 7-day checklist tailored to the session')
        } else if(fu.includes('weekly')){
          agenda.push('- Weekly micro-check prompts for the first month')
        } else {
          agenda.push('- Email summary with 3 concrete next steps')
        }

        agenda.push('\nPrepared by: '+('{{BUSINESS_NAME}}'));
        agenda.push('Contact: '+('{{EMAIL}}')+' | '+('{{PHONE}}'));

        return agenda.join('\n');
      }

      build.addEventListener('click',function(){
        out.textContent = generate();
        out.scrollIntoView({behavior:'smooth'});
      });

      cp.addEventListener('click',function(){
        if(out.textContent.trim().length===0 || out.textContent.includes('No plan')){alert('Please build a plan first.');return}
        navigator.clipboard.writeText(out.textContent).then(()=>alert('Plan summary copied.'),()=>alert('Copy failed.'));
      });

      dl.addEventListener('click',function(){
        if(out.textContent.trim().length===0 || out.textContent.includes('No plan')){alert('Please build a plan first.');return}
        const blob = new Blob([out.textContent],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = 'session-plan.txt';
        document.body.appendChild(a); a.click(); a.remove();
        URL.revokeObjectURL(url);
      });

      // Booking request button: prefill a message
      document.getElementById('submitBooking').addEventListener('click',function(){
        const nm = document.getElementById('name').value.trim();
        const em = document.getElementById('email').value.trim();
        const st = document.getElementById('sessionType').value;
        const when = document.getElementById('when').value.trim();
        const plan = out.textContent.trim();
        if(!nm || !em){alert('Please provide name and email.');return}
        const subject = encodeURIComponent('Session request from '+nm);
        let body = 'Name: '+nm+'\nEmail: '+em+'\nSession type: '+st+'\nPreferred: '+when+'\n\n';
        body += 'Session plan summary (auto):\n'+(plan||'No plan provided yet.');
        const mailto = 'mailto:{{EMAIL}}?subject='+subject+'&body='+encodeURIComponent(body);
        window.location.href = mailto;
      });
    })();
  </script>
</body>
</html>"} 
